"""Paired token/compute evidence for the registered S4 optimizer continuation."""
import json
from pathlib import Path
import numpy as np
from training.t2_real_av import write_json


def main():
    cfg=json.loads(Path("configs/t1/fineweb_extend_v2.json").read_text()); root=Path(cfg["artifacts"]); summary=json.loads((root/"summary.json").read_text()); base=json.loads(Path(cfg["parent_config"]).read_text()); card=json.loads((Path(base["corpus"])/"dataset_card.json").read_text()); parent=json.loads((Path(cfg["parent"])/"summary.json").read_text()); comparisons={}; curves={r["id"]:json.loads((root/r["id"]/"curves.json").read_text()) for r in cfg["runs"]}
    for seed in (81,82):
        a,b=[r for r in cfg["runs"] if r["seed"]==seed]; g=summary["test"][a["id"]]; s=summary["test"][b["id"]]; ca,cb=curves[a["id"]],curves[b["id"]]; common=min(ca[-1]["seconds"],cb[-1]["seconds"]); at=lambda records:float(np.interp(common,[v["seconds"] for v in records],[v["validation"]["nll"] for v in records])); va,vb=at(ca),at(cb); da=summary["runs"][a["id"]]; db=summary["runs"][b["id"]]
        parent_a=parent["runs"][a["parent"]]["wall_seconds"]; parent_b=parent["runs"][b["parent"]]["wall_seconds"]; total_common=min(parent_a+ca[-1]["seconds"],parent_b+cb[-1]["seconds"])
        def total_at(records,prior_seconds,prior_run):
            points=[{"time":prior_seconds,"nll":parent["runs"][prior_run]["selected_validation_nll"],"tokens":16777216}]+[{"time":prior_seconds+v["seconds"],"nll":v["validation"]["nll"],"tokens":v["tokens"]} for v in records]; eligible=[v for v in points if v["time"]<=total_common+1e-6]; saved=min(eligible,key=lambda v:v["nll"]); interpolated=float(np.interp(total_common,[v["time"] for v in points],np.minimum.accumulate([v["nll"] for v in points]))); return saved,interpolated
        saved_a,interp_a=total_at(ca,parent_a,a["parent"]); saved_b,interp_b=total_at(cb,parent_b,b["parent"])
        comparisons[str(seed)]={"gpt2_test_nll":g["nll"],"slwm_test_nll":s["nll"],"equal_tokens_relative_test_nll_reduction":1-s["nll"]/g["nll"],"slwm_to_gpt2_extension_wall_ratio":db["wall_seconds"]/da["wall_seconds"],"parent_seconds":{"gpt2":parent_a,"slwm":parent_b},"common_total_compute_seconds":total_common,"gpt2_saved_validation_at_common_total_compute":saved_a,"slwm_saved_validation_at_common_total_compute":saved_b,"equal_total_compute_saved_relative_validation_nll_reduction":1-saved_b["nll"]/saved_a["nll"],"equal_total_compute_interpolated_relative_validation_nll_reduction":1-interp_b/interp_a,"common_compute_method":"Includes each actual parent's training/validation time plus continuation; primary is best validation checkpoint measured before the common budget, interpolation secondary; excludes GPU queue time, not FLOP matched","extension_only_diagnostic":{"common_seconds":common,"gpt2_validation":va,"slwm_validation":vb,"relative_reduction":1-vb/va}}
    for value in comparisons.values(): value["timer_scope"]="Original parent timer includes its checkpoint I/O; continuation counters include training/validation but exclude loading/saving and lock queues. This is a measured timer-budget comparison, not exact end-to-end wall or FLOP equivalence."
    write_json(root/"comparisons.json",comparisons); lines=["# T1-S4 — larger-batch GPT-2-scale text continuation","","Optimizer-preserving continuation of four from-scratch124/125M-parameter language models. The language weights remain separate from the24M audio/video/phonetic-text world fields. This is a learning-curve study, not converged pretraining.","",f"Available training corpus: {card['tokens']['train']:,} tokens, split by registrable domain with global exact/prefix/URL deduplication. These runs consume151M/model at the full target, without repeating the registered windows. Fresh test uses524,288 tokens from reserved windows disjoint from the earlier S2 reported test sample. All choices use validation only.","","| Run | Variant / seed | Weights | Tokens seen | Selected token step | Actual optimizer updates | Test NLL / PPL | Extension minutes |","|---|---|---:|---:|---:|---:|---:|---:|"]
    for r in cfg["runs"]:
        d=summary["runs"][r["id"]]; t=summary["test"][r["id"]]; lines.append(f"| {r['id']} | {r['variant']} / {r['seed']} | {d['parameters']:,} | {d['tokens_seen']:,} | {d['selected_total_token_equivalent_step']} | {d['actual_optimizer_updates']} | {t['nll']:.4f} / {t['perplexity']:.2f} | {d['wall_seconds']/60:.2f} |")
    lines += ["","| Seed | Equal-token test NLL reduction | SLWM/GPT extension time | Equal total-time validation reduction | Interpolated total-time diagnostic |","|---|---:|---:|---:|---:|"]
    for seed,v in comparisons.items(): lines.append(f"| {seed} | {100*v['equal_tokens_relative_test_nll_reduction']:+.2f}% | {v['slwm_to_gpt2_extension_wall_ratio']:.3f}× | {100*v['equal_total_compute_saved_relative_validation_nll_reduction']:+.2f}% | {100*v['equal_total_compute_interpolated_relative_validation_nll_reduction']:+.2f}% |")
    lines += ["","Compute comparisons include each parent's measured timer plus continuation time, evaluated at the shorter shared total-time budget. The parent's original timer includes checkpoint I/O; continuation counters measure training/validation and exclude loading/saving. Both exclude GPU lock queues. This asymmetry remains explicit rather than retrospectively rewriting frozen clocks. Primary comparison uses the best recorded validation checkpoint available before that budget; interpolation is a separately labeled diagnostic. Parent compute is not free. These are timer-budget comparisons, not exact end-to-end wall or identical-FLOP budgets. Equal-token test results and equal-time validation results answer different questions. The extension-only calculation remains in comparisons.json for auditing.","","The initial512 additional updates preserve the original32×512 schedule and optimizer/RNG state. Subsequent updates use64×512 and pinned Liger fused cross entropy, preserving the exact token-window order. Validation keeps the original plain cross-entropy microbatch8. The frozen protocol records the learning-rate extension and >5% two-check overfit stop. The smaller S3 partial experiment remains intact rather than being relabeled as S4.","","At the full151M target this is only about1.2 tokens per parameter, while2.6B tokens are prepared. Quality remains undertrained; none of these artifacts establishes factual accuracy, reasoning, grounded actions, or eventual scaling superiority. Two seeds estimate reproducibility at one size, not a scaling law. Every fixed greedy/sampled continuation is retained in the run's samples.json, including poor outputs.","","The throughput study retains numerical objective/gradient checks, plain and fused alternatives, slower cases and the128-batch out-of-memory result. Selecting64 uses measured throughput rather than maximizing memory occupancy. Both architectures receive the same runtime revision. Checkpoints retain selected/resume optimizer and RNG states, source snapshots, token counts and final weights."]
    (root/"report.md").write_text("\n".join(lines)+"\n"); import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
    fig,axes=plt.subplots(2,2,figsize=(11,8),layout="constrained")
    for column,seed in enumerate((81,82)):
        for r in cfg["runs"]:
            if r["seed"]!=seed: continue
            c=curves[r["id"]]; prior_seconds=parent["runs"][r["parent"]]["wall_seconds"]; axes[0,column].plot([v["tokens"]/1e6 for v in c],[v["validation"]["nll"] for v in c],label=r["variant"]); axes[1,column].plot([(prior_seconds+v["seconds"])/60 for v in c],[v["validation"]["nll"] for v in c],label=r["variant"])
        axes[0,column].set_title("Seed "+str(seed)); axes[0,column].set_xlabel("Cumulative training tokens (millions)"); axes[1,column].set_xlabel("Total measured training/validation minutes")
        for ax in axes[:,column]: ax.set_ylabel("Held-domain validation NLL"); ax.grid(alpha=.2); ax.legend()
    fig.suptitle("GPT-2 versus SLWM · paired124/125M text models\nEqual data and measured compute; separate from audiovisual weights"); fig.savefig(root/"learning_curves.png",dpi=170); plt.close(fig); print(json.dumps({"extended_text_report":True,"comparisons":comparisons}))


if __name__=="__main__": main()
